module Main (main) where

import Control.Monad (unless)
import System.Exit (exitFailure)

import Evaluator (evaluate)

data Expected = Value Double | Failure

cases :: [(String, Expected)]
cases =
  [ -- Sanity checks (should have worked before the fixes too)
    ("2 + 3 * 4",           Value 14)
  , ("10 - 4 - 3",          Value 3)
  , ("(1+2) * 3",           Value 9)
  , ("7 // 2",              Value 3)
  , ("-7 // 2",             Value (-4))
  , ("7 % 3",               Value 1)
  , ("-7 % 3",              Value 2)
  , ("0.1 + 0.2",           Value 0.3)
  , ("--3",                 Value 3)
  , ("2 * -3",              Value (-6))

    -- Fix 1: leading dot
  , (".5 + 1",              Value 1.5)
  , (".25 * 4",             Value 1)

    -- Fix 2: trailing dot
  , ("3. + 1",              Value 4)
  , ("3. + 1.5",            Value 4.5)
  , (".5 + 3.",             Value 3.5)
  , (".",                   Failure)    -- a lone dot is still an error
  , ("3..",                 Failure)

    -- Fix 3: ** is right-associative
  , ("2 ** 3 ** 2",         Value 512)
  , ("2 ** 2 ** 4",         Value 65536)
  , ("(1+1/(2**1**0))",     Value 1.5)

    -- Unary minus binds tighter than ** (kept from the original)
  , ("-2 ** 2",             Value 4)
  , ("-2 ** 3",             Value (-8))
  , ("2 ** -1",             Value 0.5)
  , ("-4 ** 0.5",           Failure)    -- (-4) ** 0.5 is imaginary
  , ("-4 ** -0.5",          Failure)
  , ("-4 ** -2",            Value 0.0625)

    -- Fix 4: leftover tokens are errors
  , ("1 2",                 Failure)
  , ("(1+2))",              Failure)
  , ("2(3+4)",              Failure)

    -- Fix 5: NaN and Infinity are errors
  , ("10 ** 400",           Failure)
  , ("(-8) ** 0.5",         Failure)
  , ("0 ** -1",             Failure)
  , ('1' : replicate 400 '0', Failure)  -- literal too large for a Double

    -- Fix 6: small divisors are valid, zero divisors are not
  , ("1 / 0.0000000001",    Value 1e10)
  , ("1 / 0",               Failure)
  , ("1 % 0",               Failure)
  , ("1 // 0",              Failure)

    -- Malformed input should give an error, never a crash
  , ("",                    Failure)
  , ("   ",                 Failure)
  , ("2 +",                 Failure)
  , ("*3",                  Failure)
  , ("(1+2",                Failure)
  , ("2 $ 3",               Failure)
  ]

-- A Value matches if it is within a small relative tolerance;
-- a Failure matches any Left.
passes :: Expected -> Either String Double -> Bool
passes (Value want) (Right got) = abs (got - want) <= 1e-9 * max 1 (abs want)
passes Failure      (Left _)    = True
passes _            _           = False

run :: (String, Expected) -> IO Bool
run (input, expected) = do
  let actual = evaluate input
      ok     = passes expected actual
      shown  = if length input > 30 then take 27 input ++ "..." else input
  putStrLn ((if ok then "PASS  " else "FAIL  ") ++ show shown ++ " => " ++ show actual)
  return ok

main :: IO ()
main = do
  results <- mapM run cases
  let failures = length (filter not results)
  putStrLn (show (length cases - failures) ++ "/" ++ show (length cases) ++ " passed")
  unless (failures == 0) exitFailure
